import React, { useState, useEffect } from 'react';
import { Flow } from 'flow-sdk';
import { 
  SectionLabel, 
  PillButton, 
  FieldDropdown, 
  TextInput 
} from './components/Primitives';
import { CardPreview } from './components/CardPreview';

const OCCASIONS = ['Birthday', 'Anniversary', 'Graduation', 'Wedding', 'Sympathy', 'Thank You', 'Get Well', 'Just Because'];
const FLORAL_STYLES = ['Romantic Roses', 'Wildflower Meadow', 'Tropical Paradise', 'Elegant Lilies', 'Sunlit Sunflowers', 'Minimalist Tulips', 'Vintage Pastel'];
const BACKGROUNDS = ['Neutral Studio', 'Rustic Wood', 'Dark Marble', 'Sunlit Garden', 'Misty Morning', 'Art Gallery', 'Cozy Cottage'];
const ART_STYLES = ['Cinematic Photo', 'Watercolor', 'Oil Painting', 'Digital Illustration', 'Pencil Sketch', 'Hyper-Realistic', 'Soft Pastel'];

export default function App() {
  const [occasion, setOccasion] = useState(OCCASIONS[0]);
  const [floralStyle, setFloralStyle] = useState(FLORAL_STYLES[0]);
  const [background, setBackground] = useState(BACKGROUNDS[0]);
  const [artStyle, setArtStyle] = useState(ART_STYLES[0]);
  const [note, setNote] = useState('');
  const [isFlipped, setIsFlipped] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isSuggesting, setIsSuggesting] = useState(false);
  const [generatedImage, setGeneratedImage] = useState<{ base64: string; mimeType: string; mediaId: string } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [exportState, setExportState] = useState<'idle' | 'processing' | 'done'>('idle');
  const [shareState, setShareState] = useState<'idle' | 'sharing' | 'shared'>('idle');

  useEffect(() => {
    const id = 'bouquet-fonts';
    if (!document.getElementById(id)) {
      const link = document.createElement('link');
      link.id = id;
      link.rel = 'stylesheet';
      link.href = 'https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=Inter:wght@400;500&display=swap';
      document.head.appendChild(link);
    }

    const styleId = 'global-styles';
    if (!document.getElementById(styleId)) {
      const style = document.createElement('style');
      style.id = styleId;
      style.textContent = `
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fade-in { animation: fadeIn 0.5s ease-out forwards; }
        .dark-scrollbar::-webkit-scrollbar { width: 6px; }
        .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 10px; }

        .perspective-1000 { perspective: 1000px; }
        .preserve-3d { transform-style: preserve-3d; }
        .backface-hidden { 
          backface-visibility: hidden; 
          -webkit-backface-visibility: hidden; 
        }
        .rotate-y-180 { transform: rotateY(180deg); }
        .rotate-y-0 { transform: rotateY(0deg); }

        .card-inner {
          transition: transform 0.7s cubic-bezier(0.4, 0, 0.2, 1);
        }
      `;
      document.head.appendChild(style);
    }
  }, []);

  const handleGenerateBouquet = async () => {
    setIsGenerating(true);
    setError(null);
    setIsFlipped(false);
    try {
      const prompt = `A ${artStyle} of a high-end floral arrangement for a ${occasion}. Floral arrangement style: ${floralStyle}. Set against a ${background} background. High detail, beautiful lighting, 8k resolution.`;
      const result = await Flow.generate.image({
        prompt,
        modelDisplayName: '🍌 Nano Banana Pro',
        aspectRatio: '3:4',
      });
      setGeneratedImage(result);
    } catch (err) {
      setError('Failed to generate bouquet.');
    } finally {
      setIsGenerating(false);
    }
  };

  const handleSuggestNote = async () => {
    setIsSuggesting(true);
    try {
      const { text } = await Flow.generate.text(
        `Write a short, heartfelt ${occasion} note for a flower card. Max 120 chars.`,
        { systemInstruction: 'You are a poetic greeting card writer.' }
      );
      setNote(text.replace(/^"|"$/g, '').trim());
      setIsFlipped(true);
    } catch (err) {
      setError('Failed to suggest a note.');
    } finally {
      setIsSuggesting(false);
    }
  };

  const createCardCanvas = async (): Promise<HTMLCanvasElement> => {
    if (!generatedImage) throw new Error('No image');
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('Canvas error');
    canvas.width = 3000;
    canvas.height = 2000;
    const img = new Image();
    img.src = `data:${generatedImage.mimeType};base64,${generatedImage.base64}`;
    await new Promise((resolve) => { img.onload = resolve; });
    ctx.drawImage(img, 0, 0, 1500, 2000);
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(1500, 0, 1500, 2000);
    ctx.textAlign = 'center';
    ctx.fillStyle = '#9ca3af';
    ctx.font = '500 40px Inter';
    ctx.fillText(occasion.toUpperCase(), 2250, 400);
    ctx.fillStyle = '#e5e7eb';
    ctx.fillRect(2150, 450, 200, 2);
    ctx.fillStyle = '#1f2937';
    ctx.font = 'italic 90px "Instrument Serif"';
    const words = (note || "With Love").split(' ');
    let line = '';
    let y = 800;
    const maxWidth = 1100;
    const lineHeight = 110;
    for (let n = 0; n < words.length; n++) {
      const testLine = line + words[n] + ' ';
      const metrics = ctx.measureText(testLine);
      if (metrics.width > maxWidth && n > 0) {
        ctx.fillText(line, 2250, y);
        line = words[n] + ' ';
        y += lineHeight;
      } else {
        line = testLine;
      }
    }
    ctx.fillText(line, 2250, y);
    ctx.fillStyle = '#f3f4f6';
    ctx.font = 'normal 120px "Material Symbols Outlined"';
    ctx.fillText('spa', 2250, 1700);
    return canvas;
  };

  const handleExport = async (mode: 'download' | 'share') => {
    if (!generatedImage) return;
    if (mode === 'download') setExportState('processing');
    else setShareState('sharing');
    try {
      const canvas = await createCardCanvas();
      const base64 = canvas.toDataURL('image/jpeg', 0.9).split(',')[1];
      const filename = `bouquet_card_${occasion.toLowerCase()}.jpg`;
      if (mode === 'download') {
        await Flow.download({ base64, mimeType: 'image/jpeg', filename });
        setExportState('done');
        setTimeout(() => setExportState('idle'), 2000);
      } else {
        await Flow.save({ base64, mimeType: 'image/jpeg', name: filename });
        setShareState('shared');
        setTimeout(() => setShareState('idle'), 2000);
      }
    } catch (err) {
      setError(mode === 'download' ? 'Download failed.' : 'Share failed.');
      mode === 'download' ? setExportState('idle') : setShareState('idle');
    }
  };

  const configContent = (
    <div className="flex flex-col gap-[24px] overflow-y-auto pr-1 dark-scrollbar h-full">
      <div className="flex flex-col gap-2">
        <SectionLabel>Card Configuration</SectionLabel>
        <div className="flex flex-col gap-1.5">
          <FieldDropdown label="Occasion" value={occasion} options={OCCASIONS} onChange={setOccasion} />
          <FieldDropdown label="Floral Arrangement" value={floralStyle} options={FLORAL_STYLES} onChange={setFloralStyle} />
          <FieldDropdown label="Background" value={background} options={BACKGROUNDS} onChange={setBackground} />
          <FieldDropdown label="Art Style" value={artStyle} options={ART_STYLES} onChange={setArtStyle} />
        </div>
      </div>

      <div className="flex flex-col gap-2">
        <SectionLabel>Personal Note</SectionLabel>
        <div className="flex flex-col gap-1.5">
          <TextInput value={note} onChange={setNote} placeholder="Write your message..." />
          <PillButton 
            variant="outline" 
            onClick={handleSuggestNote}
            icon={<span className="material-symbols-outlined text-[18px]">{isSuggesting ? 'sync' : 'auto_awesome'}</span>}
          >
            {isSuggesting ? 'Writing...' : 'Suggest a note'}
          </PillButton>
        </div>
      </div>

      {error && (
        <div className="p-2 rounded-lg bg-red-500/10 border border-red-500/20 text-red-400 text-[11px] text-center">
          {error}
        </div>
      )}
    </div>
  );

  const actionButtons = (
    <div className="flex flex-col gap-[5px] w-full">
      <PillButton 
        variant="outline" 
        onClick={() => setIsFlipped(!isFlipped)}
        icon={<span className="material-symbols-outlined text-[18px]">cached</span>}
      >
        {isFlipped ? 'View Bouquet' : 'View Note'}
      </PillButton>
      <PillButton 
        variant="solid" 
        onClick={handleGenerateBouquet}
        disabled={isGenerating}
        icon={<span className="material-symbols-outlined text-[18px]">{isGenerating ? 'refresh' : 'palette'}</span>}
      >
        {isGenerating ? 'Arranging...' : 'Generate Bouquet'}
      </PillButton>

      {generatedImage && (
        <div className="flex gap-1 w-full">
          <PillButton 
            variant="outline" 
            onClick={() => handleExport('share')}
            disabled={shareState !== 'idle'}
            icon={<span className="material-symbols-outlined text-[18px]">share</span>}
          >
            {shareState === 'sharing' ? '...' : shareState === 'shared' ? '✓' : 'Share'}
          </PillButton>
          <PillButton 
            variant="filled" 
            onClick={() => handleExport('download')}
            disabled={exportState !== 'idle'}
            icon={<span className="material-symbols-outlined text-[18px]">download</span>}
          >
            {exportState === 'processing' ? '...' : exportState === 'done' ? '✓' : 'Get JPG'}
          </PillButton>
        </div>
      )}
    </div>
  );

  return (
    <div className="flex flex-col lg:flex-row h-full w-full bg-[#0e0e0e] text-white overflow-hidden font-['Inter']">

      {/* Configuration Section: Sidebar on desktop, bottom sheet on mobile */}
      <div className="order-2 lg:order-1 w-full lg:w-[300px] lg:h-full border-t lg:border-t-0 lg:border-r border-[rgba(218,220,224,0.15)] flex flex-col justify-between p-4 lg:px-[10px] lg:py-[12px] bg-[#0e0e0e] z-10">
        <div className="hidden lg:block flex-1 overflow-hidden">
          {configContent}
        </div>

        {/* Mobile Scrollable Config */}
        <div className="lg:hidden flex-1 overflow-y-auto max-h-[40vh] mb-4 dark-scrollbar">
          {configContent}
        </div>

        <div className="shrink-0 pt-2 lg:pt-4">
          {actionButtons}
        </div>
      </div>

      {/* Preview Section: Top on mobile, center on desktop */}
      <div className="order-1 lg:order-2 flex-1 relative flex items-center justify-center p-6 lg:p-12 bg-[#111] overflow-hidden">
        <div className="w-full max-w-[320px] lg:max-w-[450px]">
          <CardPreview 
            image={generatedImage} 
            note={note} 
            occasion={occasion}
            isGenerating={isGenerating}
            isFlipped={isFlipped}
          />
        </div>
      </div>

    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';

export const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
      {children}
    </span>
  </div>
);

export const PillButton: React.FC<{
  icon?: React.ReactNode; 
  children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; 
  onClick?: () => void;
  disabled?: boolean;
}> = ({ icon, children, variant = 'filled', onClick, disabled }) => {
  const base = 'flex items-center gap-[2px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] pl-[8px] pr-[24px] py-1 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] pl-[8px] pr-[16px] py-2 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] pl-[8px] pr-[16px] py-2 select-none',
  };
  return (
    <button className={`${base} ${variants[variant]}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center w-6 h-6">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

export const FieldDropdown: React.FC<{
  label: string; 
  value: string; 
  options: string[];
  onChange: (val: string) => void; 
  className?: string;
}> = ({ label, value, options, onChange, className = '' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const listener = (event: MouseEvent | TouchEvent) => {
      if (!ref.current || ref.current.contains(event.target as Node)) return;
      setIsOpen(false);
    };
    document.addEventListener('mousedown', listener);
    return () => document.removeEventListener('mousedown', listener);
  }, []);

  return (
    <div ref={ref} className={`relative ${className}`}>
      <button type="button" onClick={() => setIsOpen(!isOpen)}
        className="w-full text-left border border-[#595959] hover:border-[#7a7a7a] transition-colors rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none focus:outline-none">
        <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-medium text-white tracking-[0.1px]">{value}</span>
          <span className={`material-symbols-outlined text-[16px] text-[rgba(218,220,224,0.5)] mr-1 transition-transform ${isOpen ? 'rotate-180' : ''}`}>keyboard_arrow_down</span>
        </div>
      </button>
      {isOpen && (
        <div className="absolute z-50 top-[calc(100%+4px)] left-0 w-full bg-[#0e0e0e] border border-[#595959] rounded-xl overflow-hidden shadow-xl backdrop-blur-md animate-fade-in origin-top">
          <div className="max-h-40 overflow-y-auto dark-scrollbar">
            {options.map((opt) => (
              <button key={opt} type="button"
                className={`w-full text-left px-2.5 py-2 text-[11px] font-medium tracking-[0.1px] hover:bg-[#1a1a1a] transition-colors ${value === opt ? 'bg-[#1a1a1a] text-white' : 'text-[rgba(218,220,224,0.9)]'}`}
                onClick={() => { onChange(opt); setIsOpen(false); }}>
                {opt}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export const TextInput: React.FC<{
  value: string; 
  onChange: (val: string) => void; 
  placeholder?: string;
}> = ({ value, onChange, placeholder }) => (
  <textarea 
    value={value} 
    onChange={(e) => onChange(e.target.value)} 
    placeholder={placeholder}
    className="border border-[#595959] hover:border-[#7a7a7a] focus:border-[#969696] rounded-xl w-full h-[80px] px-3 py-2.5 resize-none bg-transparent text-[11px] font-medium text-white placeholder-[rgba(218,220,224,0.5)] tracking-[0.1px] focus:outline-none transition-colors" 
  />
);

export const PromptModal: React.FC<{
  isOpen: boolean; 
  onAccept: (value: string) => void; 
  onCancel: () => void;
}> = ({ isOpen, onAccept, onCancel }) => {
  const [value, setValue] = useState('');
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => { if (isOpen) { setValue(''); setTimeout(() => textareaRef.current?.focus(), 50); } }, [isOpen]);

  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center" onClick={onCancel}>
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" />
      <div className="relative w-[300px] border border-[#595959] rounded-2xl overflow-hidden bg-[#1a1a1a]" onClick={(e) => e.stopPropagation()}>
        <div className="px-4 pt-4 pb-2">
          <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">Custom Prompt</span>
        </div>
        <div className="px-4 pb-3">
          <textarea ref={textareaRef} value={value} onChange={(e) => setValue(e.target.value)}
            placeholder="Describe your bouquet..."
            className="border border-[#595959] hover:border-[#7a7a7a] focus:border-[#969696] rounded-xl w-full h-[80px] px-3 py-2.5 resize-none bg-transparent text-[11px] font-medium text-white placeholder-[rgba(218,220,224,0.5)] tracking-[0.1px] focus:outline-none transition-colors" />
        </div>
        <div className="flex gap-[5px] px-4 pb-4">
          <button type="button" onClick={onCancel} className="flex-1 h-[34px] rounded-xl border border-[#595959] hover:bg-white/5 text-[12px] font-medium text-white">Cancel</button>
          <button type="button" onClick={() => onAccept(value)} className="flex-1 h-[34px] rounded-xl bg-white hover:bg-gray-200 text-[12px] font-medium text-black">Accept</button>
        </div>
      </div>
    </div>
  );
};

import React from 'react';

interface CardPreviewProps {
  image: { base64: string; mimeType: string } | null;
  note: string;
  occasion: string;
  isGenerating: boolean;
  isFlipped: boolean;
}

export const CardPreview: React.FC<CardPreviewProps> = ({ image, note, occasion, isGenerating, isFlipped }) => {
  return (
    <div className="perspective-1000 w-full max-w-[450px] aspect-[3/4] relative">
      {/* The container that actually rotates */}
      <div 
        className={`relative w-full h-full preserve-3d card-inner ${isFlipped ? 'rotate-y-180' : 'rotate-y-0'}`}
      >

        {/* FRONT FACE */}
        <div 
          className="absolute inset-0 backface-hidden bg-[#1a1a1a] rounded-2xl shadow-2xl overflow-hidden border border-[rgba(218,220,224,0.1)]"
          style={{ transform: 'rotateY(0deg) translateZ(1px)' }}
        >
          {isGenerating && (
            <div className="absolute inset-0 z-10 flex flex-col items-center justify-center bg-black/40 backdrop-blur-sm">
              <div className="w-12 h-12 border-4 border-white/20 border-t-white rounded-full animate-spin mb-4" />
              <p className="text-[14px] font-medium tracking-wide">Arranging flowers...</p>
            </div>
          )}

          {image ? (
            <img 
              src={`data:${image.mimeType};base64,${image.base64}`} 
              alt="Bouquet" 
              className="w-full h-full object-cover animate-fade-in"
            />
          ) : !isGenerating && (
            <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center text-white/30">
              <span className="material-symbols-outlined text-[64px] mb-4">local_florist</span>
              <p className="text-[14px]">The front of your card</p>
            </div>
          )}

          <div className="absolute bottom-4 right-4 px-3 py-1 rounded-full bg-black/50 backdrop-blur-md border border-white/10 flex items-center gap-1.5">
            <span className="material-symbols-outlined text-[14px] text-white/70">sticky_note_2</span>
            <span className="text-[10px] uppercase tracking-wider text-white/70">Note on back</span>
          </div>
        </div>

        {/* BACK FACE */}
        <div 
          className="absolute inset-0 backface-hidden bg-white text-black p-12 rounded-2xl shadow-2xl flex flex-col items-center justify-center text-center border border-white/10"
          style={{ transform: 'rotateY(180deg) translateZ(1px)' }}
        >
          <div className="mb-10">
            <p className="text-[12px] uppercase tracking-[3px] font-medium text-gray-400 mb-2">
              {occasion}
            </p>
            <div className="w-16 h-[1px] bg-gray-200 mx-auto" />
          </div>

          <div className="relative max-w-[85%]">
            <p className="font-['Instrument_Serif'] text-[32px] leading-tight italic text-gray-800 break-words">
              {note || "Your handwritten note will appear here..."}
            </p>
          </div>

          <div className="mt-12 opacity-20">
            <span className="material-symbols-outlined text-[32px]">spa</span>
          </div>

          <div className="absolute top-6 left-6 opacity-5">
             <span className="material-symbols-outlined text-[48px]">auto_awesome</span>
          </div>
        </div>

      </div>
    </div>
  );
};
